window.SIDIF_STORE = {
  // Inisialisasi Database
  init() {
    if (!localStorage.getItem(STORAGE_KEYS.CASES)) {
      localStorage.setItem(STORAGE_KEYS.CASES, JSON.stringify(SEED_CASES));
    }
    if (!localStorage.getItem(STORAGE_KEYS.AUDIT)) {
      const initialLogs = [
        {
          id: "log-init",
          timestamp: new Date().toISOString(),
          userId: "SYSTEM",
          action: "INITIALIZE_DATABASE",
          details: "Inisialisasi 277 data kasus difteri Jawa Timur periode M1-M43 tahun 2026 (SIDIPro Dinkes Jatim)"
        }
      ];
      localStorage.setItem(STORAGE_KEYS.AUDIT, JSON.stringify(initialLogs));
    }
    if (!localStorage.getItem(STORAGE_KEYS.SETTINGS)) {
      localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify({
        appName: "SIDIF JAWA TIMUR",
        welcomeText: "SIDIF (Surveilans Imunisasi & Difteri Terintegrasi Jawa Timur)",
        lastUpdated: "30 Oktober 2026",
        version: "3.0"
      }));
    }
  },

  // Ambil Semua Kasus dengan Filter Opsional
  getCases(filters = {}) {
    this.init();
    let cases = JSON.parse(localStorage.getItem(STORAGE_KEYS.CASES) || "[]");
    
    // Filter kasus yang belum di-soft-delete
    cases = cases.filter(c => !c.deletedAt);

    if (filters.region && filters.region !== "all" && filters.region !== "Jawa Timur" && filters.region !== "Provinsi Jawa Timur") {
      cases = cases.filter(c => c.kabupaten === filters.region || c.kabupaten === "Kabupaten " + filters.region || c.kabupaten === "Kota " + filters.region);
    }
    if (filters.kecamatan && filters.kecamatan !== "all") {
      cases = cases.filter(c => c.kecamatan === filters.kecamatan);
    }
    if (filters.klasifikasi && filters.klasifikasi !== "all") {
      cases = cases.filter(c => c.klasifikasiKlinis === filters.klasifikasi);
    }
    if (filters.year && filters.year !== "all") {
      cases = cases.filter(c => {
        if (!c.tanggalOnset) return false;
        return new Date(c.tanggalOnset).getFullYear().toString() === filters.year.toString();
      });
    }
    if (filters.month && filters.month !== "all") {
      cases = cases.filter(c => {
        if (!c.tanggalOnset) return false;
        return (new Date(c.tanggalOnset).getMonth() + 1).toString() === filters.month.toString();
      });
    }
    if (filters.statusAdmin && filters.statusAdmin !== "all") {
      cases = cases.filter(c => c.statusAdmin === filters.statusAdmin);
    }

    return cases;
  },

  // Ambil Kasus berdasarkan ID
  getCaseById(id) {
    const cases = JSON.parse(localStorage.getItem(STORAGE_KEYS.CASES) || "[]");
    return cases.find(c => c.id === id);
  },

  // Simpan atau Perbarui Kasus
  saveCase(caseData) {
    this.init();
    const cases = JSON.parse(localStorage.getItem(STORAGE_KEYS.CASES) || "[]");
    const currentUser = window.SIDIF_AUTH ? window.SIDIF_AUTH.getCurrentUser() : null;
    const username = currentUser ? currentUser.username : "ANONYMOUS";

    if (caseData.id) {
      const index = cases.findIndex(c => c.id === caseData.id);
      if (index !== -1) {
        cases[index] = {
          ...cases[index],
          ...caseData,
          updatedAt: new Date().toISOString(),
          updatedBy: username
        };
        localStorage.setItem(STORAGE_KEYS.CASES, JSON.stringify(cases));
        this.logAudit(username, "UPDATE_CASE", `Memperbarui data kasus No Epid ${caseData.noEpid || caseData.id}`);
        return cases[index];
      }
    }

    // Tambah Kasus Baru
    const newCase = {
      ...caseData,
      id: "case-" + Date.now(),
      createdAt: new Date().toISOString(),
      createdBy: username,
      deletedAt: null,
      statusAdmin: currentUser && currentUser.role === "superadmin" ? "Terverifikasi" : "Menunggu Validasi Provinsi"
    };

    cases.unshift(newCase);
    localStorage.setItem(STORAGE_KEYS.CASES, JSON.stringify(cases));
    this.logAudit(username, "CREATE_CASE", `Menambahkan kasus difteri baru No Epid ${newCase.noEpid} atas nama ${newCase.nama}`);

    return newCase;
  },

  // Soft Delete Kasus
  deleteCase(id) {
    const cases = JSON.parse(localStorage.getItem(STORAGE_KEYS.CASES) || "[]");
    const index = cases.findIndex(c => c.id === id);
    if (index !== -1) {
      cases[index].deletedAt = new Date().toISOString();
      localStorage.setItem(STORAGE_KEYS.CASES, JSON.stringify(cases));
      const currentUser = window.SIDIF_AUTH ? window.SIDIF_AUTH.getCurrentUser() : null;
      this.logAudit(currentUser ? currentUser.username : "SYSTEM", "DELETE_CASE", `Menghapus kasus ${cases[index].noEpid || id}`);
      return true;
    }
    return false;
  },

  // Simpan Audit Log
  logAudit(userId, action, details) {
    const logs = JSON.parse(localStorage.getItem(STORAGE_KEYS.AUDIT) || "[]");
    logs.unshift({
      id: "log-" + Date.now(),
      timestamp: new Date().toISOString(),
      userId: userId || "SYSTEM",
      action: action,
      details: details
    });
    if (logs.length > 500) logs.pop();
    localStorage.setItem(STORAGE_KEYS.AUDIT, JSON.stringify(logs));
  },

  // Ambil Audit Log
  getAuditLogs(limit = 100) {
    const logs = JSON.parse(localStorage.getItem(STORAGE_KEYS.AUDIT) || "[]");
    return logs.slice(0, limit);
  },

  // Pengaturan Teks Welcome
  getSettings() {
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.SETTINGS) || "{}");
  },

  saveSettings(settings) {
    localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(settings));
  }
};

// Auto Init saat script dimuat
window.SIDIF_STORE.init();
